// ============================================================
// RARITY SYSTEM
// ============================================================
const rarities = [
        { id: "common", name: "Common", color: "#9aa8a0", glow: "rgba(154,168,160,0.25)", order: 0 },
        { id: "uncommon", name: "Uncommon", color: "#6ecf6e", glow: "rgba(110,207,110,0.30)", order: 1 },
        { id: "rare", name: "Rare", color: "#4aa8ff", glow: "rgba(74,168,255,0.35)", order: 2 },
        { id: "elite", name: "Elite", color: "#b06cff", glow: "rgba(176,108,255,0.35)", order: 3 },
        { id: "legendary", name: "Legendary", color: "#ffb84a", glow: "rgba(255,184,74,0.40)", order: 4 },
        { id: "mythic", name: "Mythic", color: "#ff4a6e", glow: "rgba(255,74,110,0.45)", order: 5 },
];

function getRarity(id) {
        return rarities.find(r => r.id === id) || rarities[0];
}

